  C({
    id: "sabeco-2017",
    ch: 3, so: 3, muc: ["3.2", "3.3", "5.2"], clo: ["CLO1", "CLO2"], nam: "2017–2020",
    vung: { en: "Vietnam", vi: "Việt Nam" },
    tieuDe: { en: "Sabeco 2017: the state sells control of Vietnam's largest brewer", vi: "Sabeco 2017: Nhà nước bán quyền chi phối hãng bia lớn nhất Việt Nam" },
    phu: { en: "A one-round competitive offering, a reserve price that became the price, a newly formed acquisition vehicle, foreign-ownership limits and a 36% stake the state kept", vi: "Chào bán cạnh tranh một vòng, giá khởi điểm trở thành giá bán, một pháp nhân mua mới thành lập, giới hạn sở hữu nước ngoài và 36% cổ phần Nhà nước giữ lại" },
    tomTat: {
      en: "In December 2017 Vietnam's Ministry of Industry and Trade sold 53.59% of Sabeco, the country's largest brewer, in a single competitive offering on the Ho Chi Minh City Stock Exchange at a starting price of VND 320,000 a share. Only two domestic investors registered: an individual for 20,000 shares and Vietnam Beverage, a company founded two months earlier that press reports linked to Thailand's ThaiBev. The state collected just under VND 110 trillion (about US$4.8 billion), almost entirely at the starting price, and kept 36%. By August 2020 the share price had fallen to VND 183,000 and the state's remaining stake was being handed to SCIC to be sold. The case asks how the state designed the sale, what the buyer actually bought, how foreign-ownership rules shaped the structure, and whether the price was good for either side.",
      vi: "Tháng 12/2017, Bộ Công Thương bán 53,59% cổ phần Sabeco, hãng bia lớn nhất Việt Nam, trong một đợt chào bán cạnh tranh duy nhất trên Sở Giao dịch Chứng khoán TP.HCM với giá khởi điểm 320.000 đồng/cổ phần. Chỉ có hai nhà đầu tư trong nước đăng ký: một cá nhân mua 20.000 cổ phần và Công ty TNHH Vietnam Beverage, doanh nghiệp mới thành lập hai tháng trước mà báo chí cho là có liên quan tới tập đoàn ThaiBev của Thái Lan. Nhà nước thu gần 110 nghìn tỷ đồng (khoảng 4,8 tỷ USD), gần như toàn bộ ở mức giá khởi điểm, và giữ lại 36%. Đến tháng 8/2020, giá cổ phiếu giảm còn 183.000 đồng và phần vốn còn lại của Nhà nước được chuyển về SCIC để thoái vốn. Tình huống hỏi Nhà nước đã thiết kế thương vụ ra sao, bên mua thực sự mua được gì, quy định sở hữu nước ngoài định hình cấu trúc thương vụ thế nào, và mức giá có hợp lý với mỗi bên hay không.",
    },
    soLieu: {
      en: [["Offering (18 Dec 2017)", "343,662,587 shares = 53.59% of charter capital; starting price VND 320,000"], ["Result", "Highest winning price VND 320,500; average VND 320,000; proceeds over VND 109,972 bn (about US$4.8 bn)"], ["Registered bidders", "Two domestic investors: an individual (20,000 shares) and Vietnam Beverage Co., Ltd (the whole block)"], ["Ownership after the sale", "Vietnam Beverage about 53.6% · state 36% · other shareholders about 10.4% (own calculation)"], ["Buyer vehicle", "Founded October 2017; charter capital VND 681.6 bn from 7 Dec 2017; reported as 49% indirectly owned by ThaiBev's BeerCo"], ["August 2020", "SAB at VND 183,000; the state's 36% transferred from the Ministry to SCIC for full divestment"]],
      vi: [["Chào bán (18/12/2017)", "343.662.587 cổ phần = 53,59% vốn điều lệ; giá khởi điểm 320.000 đồng"], ["Kết quả", "Giá đặt mua thành công cao nhất 320.500 đồng; bình quân 320.000 đồng; thu về hơn 109.972 tỷ đồng (khoảng 4,8 tỷ USD)"], ["Nhà đầu tư đăng ký", "Hai nhà đầu tư trong nước: một cá nhân (20.000 cổ phần) và Công ty TNHH Vietnam Beverage (cả lô)"], ["Sở hữu sau thương vụ", "Vietnam Beverage khoảng 53,6% · Nhà nước 36% · cổ đông khác khoảng 10,4% (tự tính)"], ["Pháp nhân mua", "Thành lập tháng 10/2017; vốn điều lệ 681,6 tỷ đồng từ 7/12/2017; báo chí cho biết BeerCo của ThaiBev sở hữu gián tiếp 49%"], ["Tháng 8/2020", "SAB ở mức 183.000 đồng; 36% vốn nhà nước chuyển từ Bộ Công Thương về SCIC để thoái toàn bộ"]],
    },
    mucTieu: {
      en: ["Evaluate how a state seller designs the sale of a controlling block: one round or staged, broad auction or targeted, reserve price and eligibility rules.", "Value a controlling stake from the transaction price: implied equity value, earnings multiple and the premium over a reference price, and explain why the reference date matters.", "Analyse what a 53.6% stake buys when another shareholder keeps 36%, using the voting thresholds of the Law on Enterprises.", "Explain how foreign-ownership limits and the Law on Investment shape the choice of acquisition vehicle, and what this means for disclosure and regulation."],
      vi: ["Đánh giá cách người bán là Nhà nước thiết kế việc bán một khối cổ phần chi phối: một vòng hay nhiều đợt, đấu giá rộng hay hẹp, giá khởi điểm và điều kiện tham gia.", "Định giá khối cổ phần chi phối từ giá giao dịch: giá trị vốn chủ hàm ý, bội số lợi nhuận và mức thặng dư so với một giá tham chiếu, và giải thích vì sao ngày tham chiếu lại quan trọng.", "Phân tích 53,6% cổ phần mua được những quyền gì khi một cổ đông khác giữ 36%, dựa trên các ngưỡng biểu quyết của Luật Doanh nghiệp.", "Giải thích giới hạn sở hữu nước ngoài và Luật Đầu tư định hình việc chọn pháp nhân mua ra sao, và điều đó có ý nghĩa gì với công bố thông tin và quản lý nhà nước."],
    },
    noiDung: {
      en: `
<h3>1. The asset and the seller</h3>
<p>Saigon Beer–Alcohol–Beverage Corporation (Sabeco, ticker SAB on the Ho Chi Minh City Stock Exchange, HOSE) is Vietnam's largest brewer, with close to 41% of the beer market; Vietnam is the third-largest beer-consuming country in Asia after China and Japan ${T("vnbusiness2017b")}. In September 2017 the Ministry of Industry and Trade (MOIT) held 89.59% of Sabeco and planned to sell 53.59%, keeping 36%. Ho Chi Minh City Securities Corporation (HSC) valued the 53.59% stake at market at VND 87.4 trillion (US$3.85 billion), forecast 2017 net revenue of VND 34.6 trillion and post-tax profit of VND 4.9 trillion, and noted that Asahi, CUB and Heineken had long been interested in the company, while the market speculated that Thai Beverage might have an advantage ${T("vns2017")}. Heineken itself had held 5.31% of Sabeco since 2008 ${T("insidebeer2020")}.</p>

<h3>2. How the state chose to sell</h3>
<p>HSC expected that the stake might be sold in stages — a small first auction to discover the price, then later sales — as the state had done with its Vinamilk shares ${T("vns2017")}. MOIT instead offered the whole block at once in a <b>competitive offering</b> (<i>chào bán cạnh tranh</i>): 343,662,587 shares, 53.59% of charter capital, at a starting price of VND 320,000 a share, with the offering on 18 December 2017 ${T("vneconomy2017")}. The shares would change hands as negotiated trades through HOSE or outside its system, settled through the Vietnam Securities Depository, between 18 December 2017 and 16 January 2018 ${T("nhadautu2017")}.</p>
<p>Two rules shaped who could bid. First, foreign ownership of Sabeco was capped at 49%; because foreign investors already held more than 9%, the ministry said foreign buyers could take at most 38.59% in this sale ${T("vneconomy2017")}. Second, an investor whose purchase would take it to 25% or more of the shares had to register separately ${T("nhadautu2017")}.</p>
<div class="ib-exhibit"><b>Exhibit 1 — Terms and result of the offering</b>
<table class="tbl"><tr><td>Shares offered</td><td>343,662,587 (53.59% of charter capital)</td></tr>
<tr><td>Starting price</td><td>VND 320,000 per share</td></tr>
<tr><td>Registered investors (deadline 17 Dec)</td><td>Two, both domestic: an individual for 20,000 shares (deposit VND 640 million); an organisation for the whole block (Vietcombank guarantee of US$484.89 million)</td></tr>
<tr><td>Winning prices</td><td>Highest VND 320,500 · lowest VND 320,000 · average VND 320,000</td></tr>
<tr><td>Proceeds to the state</td><td>Over VND 109,972 billion (about US$4.8 billion)</td></tr></table>
<p class="small muted">Sources: ${TN([["vneconomy2017"], ["vnbusiness2017b"], ["vnbusiness2017a"]])}.</p></div>

<h3>3. The bidder</h3>
<p>On 12 December HOSE announced that Vietnam Beverage Co., Ltd was the only investor registered to buy a block taking it to 25% or more of Sabeco; SAB shares rose by the 7% daily limit to VND 313,500 that morning ${T("nhadautu2017")}. Vietnam Beverage had been founded in early October 2017 with charter capital of VND 100 billion, owned at first by Nga Son Investment JSC, itself set up on 27 September 2017. On 7 December its capital was raised to VND 681.6 billion and its ownership passed to F&amp;B Alliance Vietnam Investment JSC; its new legal representative was Michael Chye Hin Fah, a Singaporean director of Fraser and Neave, a group controlled by Thai billionaire Charoen Sirivadhanabhakdi ${T("vneconomy2017")}. Press reports described Vietnam Beverage as 49% indirectly owned by BeerCo Ltd, a ThaiBev subsidiary ${TN([["vtc2020"], ["vnbusiness2017b"]])}. It had registered to buy 327 million shares, about 51% ${T("vnbusiness2017b")}.</p>

<h3>4. The result</h3>
<p>On 18 December MOIT announced that one individual and one domestic organisation had bought all 343,662,587 shares; the highest winning price was VND 320,500 and the lowest and average VND 320,000, for total proceeds of more than VND 109,972 billion ${T("vnbusiness2017a")}. No competing strategic bidder took part ${T("vnbusiness2017b")}. The state's remaining 36% was described at the time as preserving its veto ${T("nhadautu2017")}.</p>
<div class="ib-exhibit"><b>Exhibit 2 — Shareholders of Sabeco before and after the sale (% of charter capital)</b>
<table class="tbl"><tr><th></th><th>Before (Sept 2017)</th><th>After (Dec 2017)</th></tr>
<tr><td>State (MOIT)</td><td>89.59</td><td>36.00</td></tr>
<tr><td>Vietnam Beverage</td><td>—</td><td>about 53.59</td></tr>
<tr><td>Other shareholders (including Heineken, 5.31)</td><td>about 10.41</td><td>about 10.41</td></tr></table>
<p class="small muted">Sources: ${TN([["vns2017"], ["vnbusiness2017a"], ["insidebeer2020"]])}; the “other shareholders” line is 100% less the rest (own calculation). The individual's 20,000 shares are about 0.003%.</p></div>

<h3>5. The rules in force in 2017</h3>
<div class="ib-exhibit"><b>Exhibit 3 — Two legal provisions</b>
<p><b>Law on Investment 2014, Art. 23.</b> An economic organisation must meet the conditions and procedures that apply to foreign investors when it invests by buying shares if foreign investors hold 51% or more of its charter capital (or if such organisations, alone or with foreign investors, hold 51% or more). Organisations below that line follow the rules for domestic investors ${T("luatDT2014", "Art. 23")}. The Law on Investment 2020 changed the line to “more than 50%” ${T("luatDT2020", "Art. 23")}.</p>
<p><b>Law on Enterprises 2014, Art. 144.</b> Resolutions of the general meeting on share classes, changes of business lines, changes in management structure, investments or asset sales worth 35% or more of total assets, and reorganisation or dissolution pass with at least 65% of the votes of the shareholders attending; other resolutions need at least 51% of the votes attending; unless the charter says otherwise, directors are elected by cumulative voting ${T("luatDN2014", "Art. 144")}. The Law on Enterprises 2020 keeps the 65% threshold ${T("luatDN2020", "Art. 148")}.</p></div>

<h3>6. Afterwards</h3>
<p>The Prime Minister's divestment list for 2020 included Sabeco among the companies to be transferred from MOIT to the State Capital Investment Corporation (SCIC) by 31 August for the state to sell its entire holding. The state then held 36% (230.8 million shares), worth over VND 42,000 billion at the latest price of VND 183,000; SCIC took over on 28 August 2020 ${T("vtc2020")}. The stake was to be sold by the end of 2020; Heineken had sold about 0.81% of Sabeco in 2019 and kept 4.32% ${T("insidebeer2020")}. Whether and when the state's 36% was sold is left for students to check in SCIC's and Sabeco's own disclosures.</p>`,
      vi: `
<h3>1. Tài sản và người bán</h3>
<p>Tổng công ty cổ phần Bia – Rượu – Nước giải khát Sài Gòn (Sabeco, mã SAB trên Sở Giao dịch Chứng khoán TP.HCM, HOSE) là hãng bia lớn nhất Việt Nam với gần 41% thị phần bia; Việt Nam là nước tiêu thụ bia lớn thứ ba châu Á sau Trung Quốc và Nhật Bản ${Tv("vnbusiness2017b")}. Tháng 9/2017, Bộ Công Thương nắm 89,59% Sabeco và dự kiến bán 53,59%, giữ lại 36%. Công ty Chứng khoán TP.HCM (HSC) ước giá trị thị trường của khối 53,59% là 87,4 nghìn tỷ đồng (3,85 tỷ USD), dự báo doanh thu thuần năm 2017 đạt 34,6 nghìn tỷ đồng và lợi nhuận sau thuế 4,9 nghìn tỷ đồng, đồng thời cho biết Asahi, CUB và Heineken đã để mắt tới Sabeco từ lâu, còn thị trường đồn đoán Thai Beverage có thể có lợi thế ${Tv("vns2017")}. Bản thân Heineken đã nắm 5,31% Sabeco từ năm 2008 ${Tv("insidebeer2020")}.</p>

<h3>2. Nhà nước chọn cách bán</h3>
<p>HSC dự đoán khối cổ phần có thể được bán nhiều đợt — một cuộc đấu giá nhỏ trước để tìm giá, rồi bán tiếp trong những năm sau — như cách Nhà nước đã làm với cổ phần Vinamilk ${Tv("vns2017")}. Thay vào đó, Bộ Công Thương chào bán cả khối một lần theo phương thức <b>chào bán cạnh tranh</b>: 343.662.587 cổ phần, tương đương 53,59% vốn điều lệ, giá khởi điểm 320.000 đồng/cổ phần, ngày chào bán 18/12/2017 ${Tv("vneconomy2017")}. Cổ phần được chuyển nhượng bằng giao dịch thoả thuận qua HOSE hoặc ngoài hệ thống của HOSE, thanh toán qua Trung tâm Lưu ký Chứng khoán Việt Nam, trong khoảng từ 18/12/2017 đến 16/1/2018 ${Tv("nhadautu2017")}.</p>
<p>Hai quy định định hình ai được mua. Thứ nhất, sở hữu nước ngoài tại Sabeco bị giới hạn ở 49%; vì nhà đầu tư nước ngoài đã nắm hơn 9%, Bộ cho biết họ chỉ được mua tối đa 38,59% trong đợt này ${Tv("vneconomy2017")}. Thứ hai, nhà đầu tư mua khối lượng lớn dẫn tới sở hữu từ 25% cổ phần trở lên phải đăng ký riêng ${Tv("nhadautu2017")}.</p>
<div class="ib-exhibit"><b>Bảng 1 — Điều kiện và kết quả chào bán</b>
<table class="tbl"><tr><td>Số cổ phần chào bán</td><td>343.662.587 (53,59% vốn điều lệ)</td></tr>
<tr><td>Giá khởi điểm</td><td>320.000 đồng/cổ phần</td></tr>
<tr><td>Nhà đầu tư đăng ký (hạn chót 17/12)</td><td>Hai, đều trong nước: một cá nhân mua 20.000 cổ phần (đặt cọc 640 triệu đồng); một tổ chức mua cả lô (Vietcombank bảo lãnh 484,89 triệu USD)</td></tr>
<tr><td>Giá đặt mua thành công</td><td>Cao nhất 320.500 đồng · thấp nhất 320.000 đồng · bình quân 320.000 đồng</td></tr>
<tr><td>Nhà nước thu về</td><td>Hơn 109.972 tỷ đồng (khoảng 4,8 tỷ USD)</td></tr></table>
<p class="small muted">Nguồn: ${TNv([["vneconomy2017"], ["vnbusiness2017b"], ["vnbusiness2017a"]])}.</p></div>

<h3>3. Bên mua</h3>
<p>Ngày 12/12, HOSE thông báo Công ty TNHH Vietnam Beverage là nhà đầu tư duy nhất đăng ký mua khối lượng lớn dẫn tới sở hữu từ 25% cổ phần Sabeco trở lên; sáng hôm đó cổ phiếu SAB tăng trần 7% lên 313.500 đồng ${Tv("nhadautu2017")}. Vietnam Beverage được thành lập đầu tháng 10/2017 với vốn điều lệ 100 tỷ đồng, chủ sở hữu ban đầu là Công ty Cổ phần Đầu tư Nga Sơn, vốn cũng mới thành lập ngày 27/9/2017. Ngày 7/12, công ty tăng vốn điều lệ lên 681,6 tỷ đồng và chủ sở hữu chuyển thành Công ty Cổ phần Đầu tư F&amp;B Alliance Việt Nam; người đại diện theo pháp luật mới là ông Michael Chye Hin Fah, quốc tịch Singapore, giám đốc tại Fraser and Neave — tập đoàn do tỷ phú Thái Lan Charoen Sirivadhanabhakdi kiểm soát ${Tv("vneconomy2017")}. Báo chí cho biết Vietnam Beverage được BeerCo Ltd, công ty con của ThaiBev, sở hữu gián tiếp 49% ${TNv([["vtc2020"], ["vnbusiness2017b"]])}. Công ty đã đăng ký mua 327 triệu cổ phần, khoảng 51% ${Tv("vnbusiness2017b")}.</p>

<h3>4. Kết quả</h3>
<p>Ngày 18/12, Bộ Công Thương công bố một cá nhân và một tổ chức trong nước đã mua toàn bộ 343.662.587 cổ phần; giá đặt mua thành công cao nhất 320.500 đồng, thấp nhất và bình quân 320.000 đồng, tổng số tiền thu về hơn 109.972 tỷ đồng ${Tv("vnbusiness2017a")}. Không có đối thủ chiến lược nào cạnh tranh ${Tv("vnbusiness2017b")}. Phần 36% Nhà nước giữ lại khi đó được cho là đủ để giữ quyền phủ quyết ${Tv("nhadautu2017")}.</p>
<div class="ib-exhibit"><b>Bảng 2 — Cổ đông Sabeco trước và sau thương vụ (% vốn điều lệ)</b>
<table class="tbl"><tr><th></th><th>Trước (9/2017)</th><th>Sau (12/2017)</th></tr>
<tr><td>Nhà nước (Bộ Công Thương)</td><td>89,59</td><td>36,00</td></tr>
<tr><td>Vietnam Beverage</td><td>—</td><td>khoảng 53,59</td></tr>
<tr><td>Cổ đông khác (gồm Heineken 5,31)</td><td>khoảng 10,41</td><td>khoảng 10,41</td></tr></table>
<p class="small muted">Nguồn: ${TNv([["vns2017"], ["vnbusiness2017a"], ["insidebeer2020"]])}; dòng “cổ đông khác” là 100% trừ phần còn lại (tự tính). 20.000 cổ phần của cá nhân chỉ khoảng 0,003%.</p></div>

<h3>5. Quy định có hiệu lực năm 2017</h3>
<div class="ib-exhibit"><b>Bảng 3 — Hai điều luật</b>
<p><b>Luật Đầu tư 2014, Điều 23.</b> Tổ chức kinh tế phải đáp ứng điều kiện và thực hiện thủ tục đầu tư như nhà đầu tư nước ngoài khi góp vốn, mua cổ phần nếu có nhà đầu tư nước ngoài nắm giữ từ 51% vốn điều lệ trở lên (hoặc các tổ chức như vậy, riêng hoặc cùng nhà đầu tư nước ngoài, nắm từ 51% trở lên). Tổ chức dưới ngưỡng này thực hiện theo quy định với nhà đầu tư trong nước ${Tv("luatDT2014", "Art. 23")}. Luật Đầu tư 2020 đổi ngưỡng thành “trên 50%” ${Tv("luatDT2020", "Art. 23")}.</p>
<p><b>Luật Doanh nghiệp 2014, Điều 144.</b> Nghị quyết của Đại hội đồng cổ đông về loại cổ phần, thay đổi ngành nghề, thay đổi cơ cấu tổ chức quản lý, dự án đầu tư hoặc bán tài sản từ 35% tổng giá trị tài sản trở lên, tổ chức lại hoặc giải thể được thông qua khi có ít nhất 65% tổng số phiếu biểu quyết của cổ đông dự họp tán thành; các nghị quyết khác cần ít nhất 51%; nếu Điều lệ không quy định khác, bầu thành viên HĐQT theo phương thức bầu dồn phiếu ${Tv("luatDN2014", "Art. 144")}. Luật Doanh nghiệp 2020 giữ ngưỡng 65% ${Tv("luatDN2020", "Art. 148")}.</p></div>

<h3>6. Diễn biến sau đó</h3>
<p>Danh mục thoái vốn năm 2020 do Thủ tướng phê duyệt đưa Sabeco vào nhóm chuyển giao từ Bộ Công Thương về Tổng công ty Đầu tư và Kinh doanh vốn nhà nước (SCIC) trước ngày 31/8 để thoái toàn bộ phần vốn nhà nước. Khi đó Nhà nước nắm 36% (230,8 triệu cổ phần), trị giá hơn 42.000 tỷ đồng theo giá gần nhất 183.000 đồng; SCIC tiếp nhận từ ngày 28/8/2020 ${Tv("vtc2020")}. Phần vốn này dự kiến được bán trước cuối năm 2020; Heineken đã bán khoảng 0,81% Sabeco năm 2019 và còn giữ 4,32% ${Tv("insidebeer2020")}. Việc 36% vốn nhà nước đã được bán hay chưa, và khi nào, để sinh viên tự kiểm tra trong công bố thông tin của SCIC và Sabeco.</p>`,
    },
    cauHoi: {
      en: ["The ministry sold 53.59% in one competitive offering rather than in stages as HSC had expected. Using Rosenbaum and Pearl's comparison of broad and targeted auctions, what did the state gain and lose by this design?", "Compute the implied value of 100% of Sabeco at VND 320,000, the price–earnings multiple on HSC's 2017 profit forecast, and the premium over (a) HSC's September 2017 market valuation and (b) the 12 December closing price. Which reference price is ‘unaffected’, and why does it matter?", "After the sale, which general-meeting resolutions could Vietnam Beverage pass alone and which needed the state's votes (Law on Enterprises 2014, Art. 144)? What, then, did the buyer actually pay for?", "Why might it matter that Vietnam Beverage was reported to be 49% — not 51% — indirectly foreign-owned? Use the Law on Investment 2014, Art. 23. What should a regulator or the seller ask about the remaining 51%?", "Vietnam Beverage's charter capital was VND 681.6 billion against a purchase of about VND 110 trillion. How could the purchase have been financed, what risks does that structure create, and where would you look to find out?", "Only one serious bidder took part and paid almost exactly the starting price. Why might other brewers have stayed out? With the share price at VND 183,000 in August 2020, did the buyer overpay — and did the state sell well?"],
      vi: ["Bộ Công Thương bán 53,59% trong một đợt chào bán cạnh tranh thay vì bán nhiều đợt như HSC dự đoán. Dựa vào so sánh giữa đấu giá rộng và đấu giá hẹp của Rosenbaum và Pearl, Nhà nước được và mất gì với cách thiết kế này?", "Tính giá trị hàm ý của 100% Sabeco ở mức 320.000 đồng, hệ số giá trên lợi nhuận theo dự báo lợi nhuận 2017 của HSC, và mức thặng dư so với (a) giá trị thị trường HSC ước tính tháng 9/2017 và (b) giá đóng cửa ngày 12/12. Giá tham chiếu nào là giá ‘chưa bị ảnh hưởng’, và vì sao điều đó quan trọng?", "Sau thương vụ, nghị quyết Đại hội đồng cổ đông nào Vietnam Beverage tự thông qua được và nghị quyết nào cần phiếu của Nhà nước (Luật Doanh nghiệp 2014, Điều 144)? Vậy bên mua thực sự trả tiền cho cái gì?", "Vì sao việc Vietnam Beverage được cho là có 49% — chứ không phải 51% — sở hữu nước ngoài gián tiếp lại có thể quan trọng? Dùng Điều 23 Luật Đầu tư 2014. Cơ quan quản lý hoặc người bán nên hỏi gì về 51% còn lại?", "Vốn điều lệ của Vietnam Beverage là 681,6 tỷ đồng trong khi khoản mua khoảng 110 nghìn tỷ đồng. Khoản mua có thể đã được tài trợ thế nào, cấu trúc đó tạo ra rủi ro gì, và bạn sẽ tìm thông tin ở đâu?", "Chỉ một nhà đầu tư thực sự tham gia và trả gần đúng giá khởi điểm. Vì sao các hãng bia khác có thể đã đứng ngoài? Với giá cổ phiếu 183.000 đồng vào tháng 8/2020, bên mua có trả quá cao không — và Nhà nước có bán được giá không?"],
    },
    nguon: [["vns2017"], ["nhadautu2017"], ["vneconomy2017"], ["vnbusiness2017a"], ["vnbusiness2017b"], ["vtc2020"], ["insidebeer2020"], ["luatDT2014", "Art. 23"], ["luatDN2014", "Art. 144"], ["rp2020", "pp. 275–278"]],
  });

